export function memoryConsolidation(memoryChunks) {
  const consolidatedMemory = memoryChunks.reduce((acc, chunk) => {
    if (!acc[chunk.category]) {
      acc[chunk.category] = [];
    }
    acc[chunk.category].push(chunk.data);
    return acc;
  }, {});
  return consolidatedMemory;
}